\set ON_ERROR_STOP on
BEGIN;
SELECT set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.cac_staff WHERE active LIMIT 1),true);
SELECT set_config('request.jwt.claim.role','authenticated',true);
DO $$ DECLARE source uuid:=gen_random_uuid(); source_s uuid:=gen_random_uuid(); draft uuid; sid uuid; cat uuid; req uuid; result jsonb; f jsonb; key text; actor uuid:=auth.uid(); BEGIN
 SELECT category_id INTO cat FROM public.categories LIMIT 1;
 INSERT INTO public.content_versions(version_id,version_number,status,created_by) VALUES(source,1,'draft',actor);
 INSERT INTO public.scenarios(scenario_id,version_id,title,description,category_id,schedule_type,default_day) VALUES(source_s,source,'Fact source','Description',cat,'non_scheduled',NULL);
 INSERT INTO public.scenario_fact_copy VALUES(source_s,source,'general','original-key','Original general','https://example.org','2025','{"observation":"original","raw":[1,2]}','fact',true),(source_s,source,'cac','original-cac','Original CAC','https://example.org',NULL,'["preserve arbitrary JSON"]','context',false);
 UPDATE public.content_versions SET status='published',published_at=now() WHERE version_id=source;
 draft:=public.cms_create_draft(source,'Facts test',gen_random_uuid());
 SELECT draft_id INTO sid FROM cms_private.lineage WHERE version_id=draft AND table_name='scenarios' AND source_id=source_s;
 ASSERT (SELECT count(*)=2 FROM public.scenario_fact_copy WHERE scenario_id=sid AND version_id=draft);
 ASSERT (SELECT verified AND evidence='{"observation":"original","raw":[1,2]}'::jsonb AND semantic_key='original-key' FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='general');
 f:='[{"original_role":"general","fact_role":"general","display_text":"Edited general","source_url":"https://example.org/new","reporting_period":"2026","copy_kind":"fact"},{"original_role":"cac","fact_role":"cac","display_text":"Original CAC","source_url":"https://example.org","copy_kind":"context"}]';
 req:=gen_random_uuid();
 result:=public.cms_save_scenario_content(draft,0,req,sid,'Edited','Description',cat,NULL,'non_scheduled',NULL,'[]',f);
 ASSERT result=public.cms_save_scenario_content(draft,0,req,sid,'Edited','Description',cat,NULL,'non_scheduled',NULL,'[]',f);
 ASSERT (SELECT verified AND semantic_key='original-key' AND evidence='{"observation":"original","raw":[1,2]}'::jsonb FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='general');
 ASSERT (SELECT NOT verified AND evidence='["preserve arbitrary JSON"]'::jsonb FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='cac');
 ASSERT jsonb_array_length(public.cms_read_draft(draft)->'facts')=2;
 BEGIN PERFORM public.cms_save_scenario_content(draft,0,gen_random_uuid(),sid,'Stale','Description',cat,NULL,'non_scheduled',NULL,'[]',f); RAISE EXCEPTION 'Stale accepted'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 BEGIN PERFORM public.cms_save_scenario_content(draft,1,gen_random_uuid(),sid,'Invalid','Description',cat,NULL,'non_scheduled',NULL,'[]',jsonb_set(f,'{0,scenario_id}',to_jsonb(source_s))); RAISE EXCEPTION 'Foreign relationship accepted'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Unsupported fact field or relationship'; END;
 BEGIN PERFORM public.cms_save_scenario_content(draft,1,gen_random_uuid(),sid,'Invalid','Description',cat,NULL,'non_scheduled',NULL,'[]',jsonb_set(f,'{0,display_text}','"{unresolved}"')); RAISE EXCEPTION 'Invalid copy accepted'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Invalid scenario fact content'; END;
 BEGIN PERFORM public.cms_save_scenario_content(draft,1,gen_random_uuid(),sid,'Duplicate','Description',cat,NULL,'non_scheduled',NULL,'[]',jsonb_build_array(f->0,f->0)); RAISE EXCEPTION 'Duplicate role accepted'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Invalid or duplicate fact role'; END;
 BEGIN PERFORM public.cms_save_scenario_content(draft,1,gen_random_uuid(),sid,'Evidence spoof','Description',cat,NULL,'non_scheduled',NULL,'[]',jsonb_set(f,'{0,evidence}','{}')); RAISE EXCEPTION 'Evidence override accepted'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Unsupported fact field or relationship'; END;
 ASSERT (SELECT title='Edited' FROM public.scenarios WHERE scenario_id=sid AND version_id=draft);
 ASSERT (SELECT count(*)=2 FROM public.scenario_fact_copy WHERE scenario_id=sid AND version_id=draft);
 ASSERT (SELECT revision=1 FROM cms_private.workspaces WHERE version_id=draft);
 PERFORM public.cms_save_scenario_content(draft,1,gen_random_uuid(),sid,'Edited','Description',cat,NULL,'non_scheduled',NULL,'[]',jsonb_build_array(f->0));
 ASSERT NOT EXISTS(SELECT 1 FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='cac');
 f:=jsonb_build_array(f->0,'{"original_role":null,"fact_role":"cac","display_text":"New CAC","source_url":"https://example.org","copy_kind":"fact"}'::jsonb);
 PERFORM public.cms_save_scenario_content(draft,2,gen_random_uuid(),sid,'Edited','Description',cat,NULL,'non_scheduled',NULL,'[]',f);
 ASSERT (SELECT NOT verified AND evidence='{}'::jsonb FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='cac');
 f:=jsonb_set(f,'{1,original_role}','"cac"'); f:=jsonb_set(f,'{1,verified}','true');
 PERFORM public.cms_save_scenario_content(draft,3,gen_random_uuid(),sid,'Edited','Description',cat,NULL,'non_scheduled',NULL,'[]',f);
 ASSERT (SELECT verified FROM public.scenario_fact_copy WHERE scenario_id=sid AND fact_role='cac');
 BEGIN PERFORM public.cms_save_scenario_content(draft,4,gen_random_uuid(),NULL,'Foreign fact','Description',cat,NULL,'non_scheduled',NULL,'[]',f); RAISE EXCEPTION 'Foreign existing fact accepted'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Fact must belong to selected scenario and edition'; END;
 ASSERT (SELECT display_text='Original general' AND verified AND reporting_period='2025' FROM public.scenario_fact_copy WHERE scenario_id=source_s AND fact_role='general');
 BEGIN PERFORM public.cms_save_scenario_content(source,0,gen_random_uuid(),source_s,'Bad','Description',cat,NULL,'non_scheduled',NULL,'[]',f); RAISE EXCEPTION 'Published accepted'; EXCEPTION WHEN no_data_found THEN NULL; END;
 UPDATE public.cac_staff SET active=false WHERE user_id=actor;
 BEGIN PERFORM public.cms_save_scenario_content(draft,4,gen_random_uuid(),sid,'Bad','Description',cat,NULL,'non_scheduled',NULL,'[]',f); RAISE EXCEPTION 'Revoked staff accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 UPDATE public.cac_staff SET active=true WHERE user_id=actor;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.cms_save_scenario_content(draft,4,gen_random_uuid(),sid,'Bad','Description',cat,NULL,'non_scheduled',NULL,'[]',f); RAISE EXCEPTION 'Nonstaff accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 ASSERT NOT has_function_privilege('anon','public.cms_save_scenario_content(uuid,integer,uuid,uuid,text,text,uuid,uuid,text,integer,jsonb,jsonb)','EXECUTE');
 RAISE NOTICE 'Fact copy/edit/delete/new default/eligibility/evidence/reopen/retry/stale/relationship/authorization checks passed';
END $$;
ROLLBACK;
